import { useEffect, useId, useRef, useState } from "react"
import { Image, Map, MapPinned, Upload } from "lucide-react"
import { MapFileGallery } from "@/components/MapFileGallery"
import { refreshSvgAssets } from "@/lib/svg-assets"
import { useAdminCatalog } from "@/lib/use-admin-catalog"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"
import {
  Dialog,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import {
  getAdminParams,
  type ReactAdminImageFileItem,
  type ReactAdminMapListItem,
  type ReactAdminSvgFileItem,
} from "@/lib/admin-params"
import {
  createGoogleMap,
  createGoogleOverlayMap,
  createImageMapSource,
  createMap,
  uploadMapImage,
  uploadMapSvg,
} from "@/lib/create-map-api"

type MapMode = "svg" | "image" | "google"
type GoogleMode = "empty" | "overlay"
type CatalogTab = "library" | "uploads"
type MapFile = ReactAdminSvgFileItem | ReactAdminImageFileItem
type Props = {
  open: boolean
  svgFiles: ReactAdminSvgFileItem[]
  imageFiles: ReactAdminImageFileItem[]
  onOpenChange: (open: boolean) => void
  onUploaded: (file: ReactAdminSvgFileItem) => void
  onImageUploaded: (file: ReactAdminImageFileItem) => void
  onDownloadGoogleOverlay: () => void
  onCreated: (map: ReactAdminMapListItem, shouldOpen: boolean) => void
}

function fileTitle(name: string): string {
  return name.replace(/\.[^.]+$/, "").trim() || "New map"
}

function fileOrigin(file: MapFile): CatalogTab {
  // Older bootstrap records have no origin; new catalog responses are explicit.
  return (
    file.origin ??
    (file.pathShort.includes("uploads/") || file.relativeUrl.includes("/uploads/")
      ? "uploads"
      : "library")
  )
}

const GOOGLE_OVERLAY_GUIDANCE =
  "Upload an SVG containing geoViewBox calibration and a Google map screenshot/template background."

function isGoogleOverlay(file: MapFile | null): file is ReactAdminSvgFileItem {
  const svg = file as ReactAdminSvgFileItem | null
  return svg?.geoCalibrated === true && svg.googleOverlay === true
}

function previewUrl(source: string): string | undefined {
  try {
    const url = new URL(source, getAdminParams().homeUrl || window.location.origin)
    if (url.protocol === "http:" || url.protocol === "https:") return url.href
  } catch {
    /* Invalid catalog URLs cannot be used as image previews. */
  }
}

export function CreateMapDialog({
  open,
  svgFiles,
  imageFiles,
  onOpenChange,
  onUploaded,
  onImageUploaded,
  onDownloadGoogleOverlay,
  onCreated,
}: Props) {
  const id = useId()
  const inputRef = useRef<HTMLInputElement>(null)
  const initialTabRef = useRef<HTMLButtonElement>(null)
  const [mode, setMode] = useState<MapMode>("svg")
  const [googleMode, setGoogleMode] = useState<GoogleMode>("empty")
  const [uploading, setUploading] = useState(false)
  const [catalogTab, setCatalogTab] = useState<CatalogTab>("library")
  const [query, setQuery] = useState("")
  const [selected, setSelected] = useState<MapFile | null>(null)
  const [file, setFile] = useState<File | null>(null)
  const [imageSource, setImageSource] = useState<ReactAdminSvgFileItem | null>(null)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [legacyCatalogFiles, setCatalogFiles] = useState(svgFiles)
  const [legacyCatalogLoading, setCatalogLoading] = useState(false)
  const deferred = getAdminParams().deferredCatalogs === true
  const svgCatalog = useAdminCatalog("svg", deferred && open && mode === "svg", svgFiles)
  const imageCatalog = useAdminCatalog("image", deferred && open && mode === "image", imageFiles)
  const catalogFiles = deferred ? svgCatalog.files : legacyCatalogFiles
  const currentCatalog = mode === "image" ? imageCatalog : svgCatalog
  const catalogLoading = deferred ? currentCatalog.loading : legacyCatalogLoading
  const generation = useRef(0)
  const pending = useRef(false)
  const mounted = useRef(true)
  const openRef = useRef(open)
  openRef.current = open

  useEffect(() => {
    setCatalogFiles(svgFiles)
    if (deferred || !open || !getAdminParams().svgRegistryEnabled) return
    const abort = new AbortController()
    setCatalogLoading(true)
    refreshSvgAssets(svgFiles, abort.signal).then(files => {
      if (!abort.signal.aborted) {
        setCatalogFiles(files)
        setSelected(previous => {
          const asset = previous as ReactAdminSvgFileItem | null
          return asset?.assetId ? files.find(file => file.assetId === asset.assetId) ?? previous : previous
        })
      }
    }).catch(failure => {
      if (!abort.signal.aborted) setError(failure instanceof Error ? failure.message : "The SVG library could not be loaded.")
    }).finally(() => { if (!abort.signal.aborted) setCatalogLoading(false) })
    return () => { abort.abort(); setCatalogLoading(false) }
  }, [open, svgFiles, deferred])

  useEffect(() => {
    if (!deferred || svgCatalog.loading || svgCatalog.error) return
    setSelected(previous => {
      const asset = previous as ReactAdminSvgFileItem | null
      return asset?.assetId ? svgCatalog.files.find(file => file.assetId === asset.assetId) ?? previous : previous
    })
  }, [deferred, svgCatalog.loading, svgCatalog.error, svgCatalog.files])

  useEffect(() => {
    mounted.current = true
    return () => {
      mounted.current = false
      generation.current += 1
    }
  }, [])
  useEffect(() => {
    generation.current += 1
    pending.current = false
    setBusy(false)
    setUploading(false)
    setError(null)
    if (open) {
      setMode("svg")
      setGoogleMode("empty")
      setCatalogTab("library")
      setQuery("")
      setSelected(null)
      setFile(null)
      setImageSource(null)
    }
  }, [open])

  const changeOpen = (next: boolean) => {
    // Retire immediately, before the controlled prop rerenders.
    if (!next) {
      generation.current += 1
      openRef.current = false
    }
    onOpenChange(next)
  }
  const resetSelection = () => {
    setSelected(null)
    setFile(null)
    setImageSource(null)
    setError(null)
    setQuery("")
    if (inputRef.current) inputRef.current.value = ""
  }
  const chooseFile = (next: MapFile) => {
    setSelected(next)
    setFile(null)
    setImageSource(null)
    setError(null)
  }
  const stageGoogleOverlay = async (uploadFile: File) => {
    if (pending.current) return
    pending.current = true
    setBusy(true)
    setUploading(true)
    setSelected(null)
    setFile(null)
    setError(null)
    const owner = generation.current
    const current = () => mounted.current && openRef.current && generation.current === owner
    try {
      const uploaded = await uploadMapSvg(uploadFile, true)
      if (!current()) return
      if (!isGoogleOverlay(uploaded)) {
        throw new Error(GOOGLE_OVERLAY_GUIDANCE)
      }
      if (!previewUrl(uploaded.relativeUrl)) {
        throw new Error("The uploaded overlay does not have a valid preview URL.")
      }
      onUploaded(uploaded)
      setSelected(uploaded)
    } catch (failure) {
      if (current()) setError(failure instanceof Error ? failure.message : "Overlay upload failed.")
    } finally {
      if (current()) {
        pending.current = false
        setBusy(false)
        setUploading(false)
      }
    }
  }
  const runCreation = async (uploadFile: File | null, chosenFile: MapFile | null) => {
    if (pending.current) return
    if (
      mode === "google" &&
      googleMode === "overlay" &&
      (!isGoogleOverlay(chosenFile) || !previewUrl(chosenFile.relativeUrl))
    ) {
      setError(GOOGLE_OVERLAY_GUIDANCE)
      return
    }
    if (mode !== "google" && !chosenFile && !uploadFile) {
      setError(
        `Choose ${mode === "image" ? "an image" : "an SVG file"} from the gallery or upload one.`,
      )
      return
    }
    pending.current = true
    setBusy(true)
    setError(null)
    const owner = generation.current
    const current = () => mounted.current && openRef.current && generation.current === owner
    try {
      let chosen =
        mode === "google" && googleMode === "empty" ? null : uploadFile ? null : chosenFile
      let source = uploadFile ? null : imageSource
      if (uploadFile && mode !== "google") {
        chosen =
          mode === "image" ? await uploadMapImage(uploadFile) : await uploadMapSvg(uploadFile)
        if (!current()) return
        if (mode === "image") onImageUploaded(chosen as ReactAdminImageFileItem)
        else onUploaded(chosen as ReactAdminSvgFileItem)
        setSelected(chosen)
        setFile(null)
        setCatalogTab("uploads")
        if (inputRef.current) inputRef.current.value = ""
      }
      if (!current()) return
      if (mode === "google" && chosen && !isGoogleOverlay(chosen)) {
        throw new Error(GOOGLE_OVERLAY_GUIDANCE)
      }
      if (mode === "image" && chosen && !source) {
        source = await createImageMapSource(chosen as ReactAdminImageFileItem)
        if (!current()) return
        setImageSource(source)
      }
      if (!current()) return
      if (mode === "google" || (chosen as ReactAdminSvgFileItem | null)?.googleOverlay) {
        const options = getAdminParams().options as Record<string, unknown> | null
        if (typeof options?.google_api_key !== "string" || !options.google_api_key.trim()) {
          throw new Error(
            "Configure your Google Maps API key in Settings before creating a Google map.",
          )
        }
      }
      const map =
        mode === "google" && !chosen
          ? await createGoogleMap("Google map")
          : mode === "google"
            ? await createGoogleOverlayMap(fileTitle(chosen!.name), chosen!.relativeUrl)
            : await createMap(fileTitle(chosen!.name), source?.relativeUrl ?? chosen!.relativeUrl)
      if (!mounted.current) return
      // A submitted create may commit after cancellation. Keep its row, never steal navigation.
      onCreated(map, current())
      if (current()) changeOpen(false)
    } catch (failure) {
      if (current()) setError(failure instanceof Error ? failure.message : "Map creation failed.")
    } finally {
      if (current()) {
        pending.current = false
        setBusy(false)
      }
    }
  }

  const uploadLabel =
    mode === "image"
      ? "Upload image file"
      : mode === "google"
        ? "Upload Google Maps overlay SVG"
        : "Upload SVG file"
  const uploadInput = (
    <Input
      ref={inputRef}
      id={`${id}-file`}
      aria-label={uploadLabel}
      type="file"
      accept={
        mode === "image"
          ? ".png,.jpg,.jpeg,.gif,.webp,image/png,image/jpeg,image/gif,image/webp"
          : ".svg,image/svg+xml"
      }
      disabled={busy}
      className="hidden"
      onChange={(event) => {
        const chosenFile = event.target.files?.[0] ?? null
        event.currentTarget.value = ""
        setFile(chosenFile)
        setSelected(null)
        setImageSource(null)
        setError(null)
        if (mode === "google" && googleMode === "overlay" && chosenFile)
          void stageGoogleOverlay(chosenFile)
      }}
    />
  )
  const galleryFiles =
    mode === "image"
      ? (deferred ? imageCatalog.files : imageFiles).filter(
          (item) => fileOrigin(item) === "uploads" && /^uploads\/[^/]+$/.test(item.pathShort),
        )
      : catalogFiles.filter((item) => fileOrigin(item) === catalogTab)

  const overlayPreviewUrl =
    mode === "google" && googleMode === "overlay" && isGoogleOverlay(selected)
      ? previewUrl(selected.relativeUrl)
      : undefined
  const createDisabled =
    busy || (mode === "google" && googleMode === "overlay" && !overlayPreviewUrl)

  return (
    <Dialog open={open} onOpenChange={changeOpen}>
      <DialogContent
        className="flex h-[85vh] max-h-[900px] flex-col overflow-hidden sm:max-w-5xl"
        aria-describedby={undefined}
        onOpenAutoFocus={(event) => {
          // Radix's default focus search sees only the Shadow DOM host in
          // document.activeElement and can activate every pill while iterating.
          event.preventDefault()
          initialTabRef.current?.focus()
        }}
      >
        <DialogHeader className="shrink-0">
          <DialogTitle>Create map</DialogTitle>
        </DialogHeader>
        <form
          onSubmit={(event) => {
            event.preventDefault()
            void runCreation(file, selected)
          }}
          className="flex min-h-0 flex-1 flex-col gap-4"
        >
          <Tabs
            value={mode}
            onValueChange={(next) => {
              if (!busy) {
                setMode(next as MapMode)
                setGoogleMode("empty")
                setCatalogTab(next === "image" ? "uploads" : "library")
                resetSelection()
              }
            }}
            className="min-h-0 flex-1 gap-8"
          >
            <TabsList aria-label="Map type" className="!h-11 w-full shrink-0">
              <TabsTrigger ref={initialTabRef} value="svg" disabled={busy} className="text-sm">
                <Map />
                SVG map
              </TabsTrigger>
              <TabsTrigger value="image" disabled={busy} className="text-sm">
                <Image />
                Image map
              </TabsTrigger>
              <TabsTrigger value="google" disabled={busy} className="text-sm">
                <MapPinned />
                Google map
              </TabsTrigger>
            </TabsList>
            <TabsContent
              value={mode}
              className="flex min-h-0 flex-1 flex-col gap-4"
              onWheel={(event) => event.stopPropagation()}
              onTouchMove={(event) => event.stopPropagation()}
            >
              {mode === "google" ? (
                <Tabs
                  value={googleMode}
                  onValueChange={(next) => {
                    if (!busy) {
                      setGoogleMode(next as GoogleMode)
                      resetSelection()
                    }
                  }}
                  className="min-h-0 flex-1 gap-4"
                >
                  <div
                    data-slot="google-map-type-scroll"
                    className="min-w-0 max-w-full shrink-0 overflow-x-auto overscroll-x-contain"
                  >
                    <TabsList aria-label="Google map type" className="!h-9 w-max">
                      <TabsTrigger
                        value="empty"
                        disabled={busy}
                        className="flex-none whitespace-nowrap px-4 text-sm"
                      >
                        Google Map
                      </TabsTrigger>
                      <TabsTrigger
                        value="overlay"
                        disabled={busy}
                        className="flex-none whitespace-nowrap px-4 text-sm"
                      >
                        Google Map with custom overlay
                      </TabsTrigger>
                    </TabsList>
                  </div>
                  <TabsContent
                    value={googleMode}
                    data-slot="google-map-creation"
                    className="min-h-0 flex-1 space-y-5 overflow-y-auto overscroll-contain"
                  >
                    {googleMode === "empty" ? (
                      <>
                        <p className="text-sm text-muted-foreground">
                          Click “Create map” below to create an empty Google map, then add
                          locations.
                        </p>
                      </>
                    ) : (
                      <>
                        <p className="text-sm text-muted-foreground">
                          Download a geo-calibrated SVG template, draw your overlay in a vector
                          editor, and upload the SVG here. MapSVG places it on Google Maps
                          automatically. The template screenshot is removed from the live overlay;
                          your original upload is kept.
                        </p>
                        <div data-slot="google-overlay-actions" className="flex flex-wrap gap-3">
                          <Button
                            type="button"
                            variant="outline"
                            disabled={busy}
                            onClick={onDownloadGoogleOverlay}
                          >
                            Download template
                          </Button>
                          {uploadInput}
                          <Button
                            type="button"
                            variant="outline"
                            disabled={busy}
                            onClick={() => inputRef.current?.click()}
                          >
                            <Upload />
                            Upload SVG overlay
                          </Button>
                        </div>
                        {selected && overlayPreviewUrl ? (
                          <div data-slot="google-overlay-preview" className="space-y-2">
                            <p className="text-sm">{selected.name}</p>
                            <img
                              src={overlayPreviewUrl}
                              alt={`Google overlay preview: ${selected.name}`}
                              className="max-h-96 max-w-full rounded-lg border object-contain"
                            />
                          </div>
                        ) : null}
                      </>
                    )}
                  </TabsContent>
                </Tabs>
              ) : (
                <>
                  {mode === "svg" ? (
                    <Tabs
                      value={catalogTab}
                      onValueChange={(next) => {
                        if (!busy) {
                          setCatalogTab(next as CatalogTab)
                          resetSelection()
                        }
                      }}
                      className="shrink-0"
                    >
                      <TabsList aria-label="File catalog" className="!h-9">
                        <TabsTrigger value="library" disabled={busy} className="px-4 text-sm">
                          Library
                        </TabsTrigger>
                        <TabsTrigger value="uploads" disabled={busy} className="px-4 text-sm">
                          Uploads
                        </TabsTrigger>
                      </TabsList>
                    </Tabs>
                  ) : null}
                  {uploadInput}
                  {file ? (
                    <p data-slot="pending-map-file" className="shrink-0 text-sm">
                      Selected upload: {file.name}
                    </p>
                  ) : null}
                  {deferred && currentCatalog.loading ? <p role="status" className="text-sm text-muted-foreground">Loading files…</p> : null}
                  {deferred && currentCatalog.error ? <div role="alert" className="text-sm text-destructive">{currentCatalog.error} <Button type="button" variant="link" onClick={currentCatalog.retry}>Retry</Button></div> : null}
                  <MapFileGallery
                    files={galleryFiles}
                    label={mode === "image" ? "image files" : "SVG files"}
                    query={query}
                    onQueryChange={setQuery}
                    selectedUrl={selected?.relativeUrl ?? ""}
                    onSelect={chooseFile}
                    disabled={busy || catalogLoading || Boolean(deferred && currentCatalog.error)}
                    actions={
                      mode === "image" || catalogTab === "uploads" ? (
                        <Button
                          type="button"
                          variant="outline"
                          disabled={busy}
                          onClick={() => inputRef.current?.click()}
                        >
                          <Upload />
                          {mode === "image" ? "Upload image" : "Upload SVG"}
                        </Button>
                      ) : undefined
                    }
                  />
                </>
              )}
            </TabsContent>
          </Tabs>
          {error ? (
            <p role="alert" className="shrink-0 text-sm text-destructive">
              {error}
            </p>
          ) : null}
          <DialogFooter className="shrink-0">
            <Button type="button" variant="outline" onClick={() => changeOpen(false)}>
              Cancel
            </Button>
            <Button type="submit" disabled={createDisabled || catalogLoading}>
              {busy ? (uploading ? "Uploading…" : "Creating…") : "Create map"}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  )
}
