import { Search } from "lucide-react"
import { useMemo, type ReactNode } from "react"
import { InputGroup, InputGroupAddon, InputGroupInput } from "@/components/ui/input-group"
import { getAdminParams } from "@/lib/admin-params"
import { cn } from "@/lib/utils"

export type MapFileGalleryItem = {
  name: string
  pathShort: string
  relativeUrl: string
  assetId?: number
}

type Props<T extends MapFileGalleryItem> = {
  files: T[]
  label: string
  query: string
  onQueryChange: (query: string) => void
  onSelect: (file: T) => void
  selectedUrl?: string
  disabled?: boolean
  actions?: ReactNode
}

/** Core file previews/search shared by manual creation and paid SVG attachments. */
export function MapFileGallery<T extends MapFileGalleryItem>({
  files,
  label,
  query,
  onQueryChange,
  onSelect,
  selectedUrl,
  disabled,
  actions,
}: Props<T>) {
  const filtered = useMemo(() => {
    const needle = query.trim().toLowerCase()
    return files.filter(
      (file) =>
        !needle ||
        [file.name, file.pathShort, file.relativeUrl].join(" ").toLowerCase().includes(needle),
    )
  }, [files, query])
  const homeUrl = getAdminParams().homeUrl || window.location.origin

  return (
    <div className="flex min-h-0 flex-1 flex-col gap-3">
      <div className="flex shrink-0 flex-wrap items-center gap-2">
        <InputGroup className="min-w-0 flex-1" data-disabled={disabled || undefined}>
          <InputGroupAddon><Search aria-hidden="true" /></InputGroupAddon>
          <InputGroupInput
            aria-label={`Search ${label}`}
            placeholder={`Search ${label}...`}
            value={query}
            disabled={disabled}
            onChange={(event) => onQueryChange(event.target.value)}
          />
        </InputGroup>
        {actions}
      </div>
      <div
        data-slot="map-file-gallery"
        className="min-h-0 flex-1 overflow-y-auto overscroll-contain pr-1"
      >
        {filtered.length === 0 ? (
          <p className="py-12 text-center text-sm text-muted-foreground">No {label} found.</p>
        ) : (
          <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-4">
            {filtered.map((file) => (
              <button
                key={file.assetId ? `asset:${file.assetId}` : file.relativeUrl}
                type="button"
                aria-label={`Select ${file.name}`}
                aria-pressed={selectedUrl == null ? undefined : selectedUrl === file.relativeUrl}
                data-map-file={file.relativeUrl}
                disabled={disabled}
                className={cn(
                  "flex min-w-0 cursor-pointer flex-col overflow-hidden rounded-xl border bg-background text-left hover:bg-accent disabled:pointer-events-none disabled:opacity-50",
                  selectedUrl === file.relativeUrl && "border-primary ring-2 ring-primary/30",
                )}
                onClick={() => onSelect(file)}
              >
                <div className="flex h-32 w-full items-center justify-center bg-muted/20 p-3">
                  <img
                    src={new URL(file.relativeUrl, homeUrl).href}
                    alt=""
                    loading="lazy"
                    className="max-h-full max-w-full object-contain"
                  />
                </div>
                <div className="min-w-0 border-t px-3 py-2">
                  <div className="truncate text-sm font-medium">{file.name}</div>
                  <div className="truncate text-xs text-muted-foreground">{file.pathShort}</div>
                </div>
              </button>
            ))}
          </div>
        )}
      </div>
    </div>
  )
}
